  function legacyNoteHtml(value){let html=String(value||'').replace(/[&<>]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[char]));html=html.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/~~([^~]+)~~/g,'<s>$1</s>').replace(/__([^_]+)__/g,'<u>$1</u>').replace(/\*([^*]+)\*/g,'<em>$1</em>');const lines=html.split(/\r?\n/),parts=[];let list=[];const flush=()=>{if(list.length){parts.push(`<ul>${list.map(line=>`<li>${line}</li>`).join('')}</ul>`);list=[]}};for(const line of lines){if(line.startsWith('- '))list.push(line.slice(2));else{flush();parts.push(line||'<br>')}}flush();return parts.join('<br>')}
