  function setNoteEditor(note=null){selectedNoteId=note?.id||'';$('#noteTitleInput').value=note?.title||'';$('#noteContentInput').innerHTML=note?.html?cleanNoteHtml(note.html):legacyNoteHtml(note?.content||'');$('#noteMeta').textContent=note?.updatedAt?`Edytowano: ${new Date(note.updatedAt).toLocaleString('pl-PL')}`:'Nowa niezapisana notatka';renderNotes()}
  function renderNotes(){const query=$('#notesSearch').value.trim().toLowerCase(),entries=[...noteEntries()].sort((a,b)=>b.updatedAt-a.updatedAt).filter(note=>!query||`${note.title} ${note.content}`.toLowerCase().includes(query)),fragment=document.createDocumentFragment();if(!entries.length){const empty=document.createElement('p');empty.className='notes-empty';empty.textContent=noteEntries().length?'Brak pasujących notatek.':'Brak zapisanych notatek.';fragment.append(empty)}for(const note of entries){const button=document.createElement('button');button.type='button';button.classList.toggle('active',note.id===selectedNoteId);const title=document.createElement('b'),time=document.createElement('small');title.textContent=note.title||'Notatka';time.textContent=new Date(note.updatedAt).toLocaleString('pl-PL');button.append(title,time);button.onclick=()=>setNoteEditor(note);fragment.append(button)}$('#notesList').replaceChildren(fragment)}
  function saveCurrentNote(){const title=$('#noteTitleInput').value.trim(),editor=$('#noteContentInput'),content=editor.innerText.trim();if(!title&&!content)return notice('Wpisz tytuł albo treść notatki.');if(content.length>5000)return notice('Notatka może mieć maksymalnie 5000 znaków.');const now=Date.now(),existing=noteEntries().find(note=>note.id===selectedNoteId),note=existing||{id:crypto.randomUUID(),createdAt:now};note.title=title||'Notatka';note.content=content;note.html=cleanNoteHtml(editor.innerHTML);note.updatedAt=now;if(!existing)state.settings.notebook.unshift(note);state.settings.notebook=state.settings.notebook.slice(0,50);selectedNoteId=note.id;save();setNoteEditor(note);notice('Notatka została zapisana.')}
  function deleteCurrentNote(){const note=noteEntries().find(item=>item.id===selectedNoteId);if(!note)return notice('Najpierw wybierz notatkę.');if(!confirm(`Usunąć notatkę „${note.title||'Notatka'}”?`))return;state.settings.notebook=noteEntries().filter(item=>item.id!==note.id);save();setNoteEditor();notice('Notatka została usunięta.')}
  function applyNoteFormat(format){const editor=$('#noteContentInput');editor.focus();const commands={bold:'bold',italic:'italic',underline:'underline',strike:'strikeThrough',list:'insertUnorderedList'};document.execCommand(commands[format]||format,false,null)}
  function setNotesOpen(open){$('#notesBackdrop').hidden=!open;if(open){renderNotes();setTimeout(()=>$('#notesSearch').focus(),0)}}
  $('#notesButton').onclick=()=>setNotesOpen(true);$('#notesClose').onclick=()=>setNotesOpen(false);$('#notesBackdrop').onclick=event=>{if(event.target===$('#notesBackdrop'))setNotesOpen(false)};window.addEventListener('cttm-widget-open-note',event=>{const note=noteEntries().find(item=>item.id===String(event.detail||''));if(note){setNotesOpen(true);setNoteEditor(note)}});$('#noteNew').onclick=()=>setNoteEditor();$('#noteSave').onclick=saveCurrentNote;$('#noteDelete').onclick=deleteCurrentNote;$('#notesSearch').oninput=renderNotes;$$('[data-note-format]').forEach(button=>button.onmousedown=event=>{event.preventDefault();applyNoteFormat(button.dataset.noteFormat)});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('#notesBackdrop').hidden)setNotesOpen(false)});
  $('#aboutProgram .about-grid article:last-child b').textContent='6';window.addEventListener('online',()=>{if(authUser)void syncNow()});updateStats();drawCreators();drawActive();drawArchive();showAboutPanel('program');void initializeAccount();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js?v=100').catch(()=>{});window.addEventListener('beforeunload',()=>{flushArchive();disconnect(true)});
